const projects = [
  { name: "chromium", use: { channel: "chrome" } },
  { name: "firefox",  use: {} },
  { name: "webkit",   use: {} },
];

console.log("how many browsers:", projects.length);
console.log("names:", projects.map((p) => p.name));

const tests = 5;
console.log(`${tests} tests x ${projects.length} projects = ${tests * projects.length} runs`);

const desktopFirefox = { browserName: "firefox", viewport: { width: 1280, height: 720 } };

const myFirefox = { ...desktopFirefox, viewport: { width: 1920, height: 1080 } };

console.log("preset: ", JSON.stringify(desktopFirefox));
console.log("mine:   ", JSON.stringify(myFirefox));

// Override BEFORE the spread and the preset wins — almost never what you want.
const broken = { viewport: { width: 1920, height: 1080 }, ...desktopFirefox };
console.log("broken: ", JSON.stringify(broken.viewport));

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week3/generated/day4-browsers.config.ts", `// Week 3, Days 4-5 — a config with more than one browser.
//
// The root playwright.config.ts deliberately enables Chromium only. Conditional
// skipping needs several browsers to be worth anything, so this file adds them
// without touching the shared config every other week depends on.
//
// Run with:  npx playwright test -c week3/generated/day4-browsers.config.ts
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day4-*.spec.ts", "day5-*.spec.ts"],
  fullyParallel: true,
  // 3 projects x a handful of tests: parallelism is what keeps this quick.
  workers: 3,
  reporter: [["list"]],
  use: {
    baseURL: "https://test-automation-banking.vercel.app",
    trace: "retain-on-failure",
  },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
    { name: "firefox", use: { ...devices["Desktop Firefox"] } },
    { name: "webkit", use: { ...devices["Desktop Safari"] } },
  ],
});
`);

await writeProjectFile("week3/generated/day5-crossbrowser.spec.ts", `// Week 3, Day 5 — the same tests, once per browser.
//
// Nothing here is browser-specific. That is the point: you write the test once and
// the \`projects\` array decides how many times it runs.
//
//   npx playwright test -c week3/generated/day4-browsers.config.ts
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Cross-browser", () => {
  test("signing in works on every engine", async ({ page, browserName }) => {
    await loginAs(page);
    await expect(page.getByText("Leela")).toBeVisible();

    // \`browserName\` is a built-in fixture: "chromium" | "firefox" | "webkit".
    expect(["chromium", "firefox", "webkit"]).toContain(browserName);
  });

  test("the dashboard tiles navigate on every engine", async ({ page }) => {
    await loginAs(page);
    await page.getByText("Transaction History", { exact: true }).click();
    await expect(page).toHaveURL(/accountDashboard/);
  });

  test("logging out works on every engine", async ({ page }) => {
    await loginAs(page);
    await page.getByRole("button", { name: "LogOut" }).click();
    await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
  });
});
`);

await runSpec("week3/generated/day5-crossbrowser.spec.ts", { extraArgs: ["-c", "week3/generated/day4-browsers.config.ts"] });

const tests = 9;
const perTest = 3.5;              // seconds, roughly, from the run above

for (const workers of [1, 3, 9]) {
  const wall = Math.ceil(tests / workers) * perTest;
  console.log(`workers=${String(workers).padEnd(2)} -> about ${wall.toFixed(1)}s wall clock`);
}
console.log("\n(diminishing returns past your core count — processes start competing)");

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week3/generated/day5-retries.config.ts", `// Week 3, Day 5 — a config with retries switched on.
//
// The root config sets \`retries: process.env.CI ? 2 : 0\`, so locally there are no
// retries and a flaky-by-design demo would simply fail. This config turns them on
// for one file, without changing what anyone else runs.
//
// The demo file is deliberately NOT named *.spec.ts, so the root config's
// testMatch ("week*/**/*.spec.ts") never collects it and the default suite stays
// green.
//
// Run with:  npx playwright test -c week3/generated/day5-retries.config.ts
import { defineConfig } from "@playwright/test";

export default defineConfig({
  testDir: ".",
  testMatch: ["day5-retries.retrydemo.ts"],
  retries: 2,
  reporter: [["list"]],
});
`);

await writeProjectFile("week3/generated/day5-retries.retrydemo.ts", `// Week 3, Day 5 — what a retry actually does.
//
// Filename note: this is \`.retrydemo.ts\`, not \`.spec.ts\`, on purpose. The root
// config collects every week*/**/*.spec.ts, and a file that fails on its first
// attempt would turn the default suite red. Its own config picks it up instead.
//
//   npx playwright test -c week3/generated/day5-retries.config.ts
import { test, expect } from "@playwright/test";

test.describe("Retries", () => {
  test("a test that only passes on the second attempt", async () => {
    // test.info().retry is 0 on the first run, 1 on the first retry, and so on.
    const attempt = test.info().retry;

    // Fails on attempt 0, passes on attempt 1. This is what a genuinely flaky
    // test looks like from the runner's point of view.
    expect(attempt).toBeGreaterThan(0);
  });

  test("a test that passes first time is never retried", async () => {
    expect(test.info().retry).toBe(0);
  });

  test("retries do not reset state you left outside the test", async () => {
    // Each retry is a FRESH test with fresh fixtures — but module-level state
    // survives, which is a common source of confusing retry behaviour.
    expect(test.info().retry).toBeGreaterThanOrEqual(0);
  });
});
`);

await runSpec("week3/generated/day5-retries.retrydemo.ts", { extraArgs: ["-c", "week3/generated/day5-retries.config.ts"] });

const overrides = [
  { flag: "--project=webkit",  replaces: "which projects run" },
  { flag: "--workers=1",       replaces: "workers" },
  { flag: "--retries=2",       replaces: "retries" },
  { flag: "--headed",          replaces: "use.headless" },
  { flag: "--debug",           replaces: "page.pause() in the script" },
  { flag: "--repeat-each=10",  replaces: "nothing — it re-runs, to prove a flake" },
];

for (const o of overrides) console.log(`${o.flag.padEnd(18)} -> ${o.replaces}`);

const TESTS = 400, SECONDS = 20, WORKERS = 8;
const wall = (tests: number, projects: number) =>
  ((tests * projects * SECONDS) / WORKERS / 60).toFixed(0);

console.log(`everything everywhere : ${wall(TESTS, 3).padStart(4)} min per PR`);
console.log(`tiered (PR)           : ${wall(TESTS, 1).padStart(4)} min per PR`);
console.log(`tiered (nightly)      : ${wall(TESTS, 3).padStart(4)} min overnight`);
console.log(`smoke on 3 + full on 1: ${wall(TESTS, 1)} + ${wall(40, 3)} min per PR`);

const failRate = [0.5, 0.3, 0.1, 0.02];

console.log("per-run fail rate -> chance the SUITE still goes red, by retries");
for (const p of failRate) {
  const cells = [1, 2, 3].map((r) => (p ** (r + 1) * 100).toFixed(2).padStart(6) + "%");
  console.log(`  ${(p * 100).toFixed(0).padStart(3)}%  ->  ${cells.join("  ")}`);
}
console.log("                        retries=1  retries=2  retries=3");
